        for (int i = 0; i < list.Length; i++)
        {
            if (list[i].p_ppid == 0)
            {
                // skip kernel threads
                numProcesses -= 1;
            }
            else
            {
                pids[idx] = list[i].p_pid;
                idx += 1;
            }
        }

        // Remove extra elements
        Array.Resize<int>(ref pids, numProcesses);
        return pids;
    }
    finally
    {
        NativeMemory.Free(entries);
