private static int get_hash_code(
    ObjectNode objectNode,
    INodeWithTypeSignature node,
    ObjectNode.ObjectData data)
{
    HashCode hash = new HashCode();
    hash.Add(WasmLowering.GetSignature(node).FuncType);
